def transform(grid):
    h, w = len(grid), len(grid[0])

    # The color key is a repeated nonempty row.
    key = None
    r = 0
    while r < h:
        end = r + 1
        while end < h and grid[end] == grid[r]:
            end += 1
        if end - r >= 2 and any(grid[r]):
            key = (r, end)
            break
        r = end

    if key is None:
        return [row[:] for row in grid]

    r0, r1 = key
    key_cols = [c for c, v in enumerate(grid[r0]) if v]
    palette = [grid[r0][c] for c in key_cols]
    key_cells = {(rr, c) for rr in range(r0, r1) for c in key_cols}

    # Locate the motif in the non-key occurrence of a palette color.
    motif_cells = None
    motif_color = None
    for color in palette:
        remaining = {
            (rr, cc)
            for rr in range(h) for cc in range(w)
            if grid[rr][cc] == color and (rr, cc) not in key_cells
        }
        if not remaining:
            continue

        components = []
        while remaining:
            start = remaining.pop()
            comp = {start}
            stack = [start]
            while stack:
                rr, cc = stack.pop()
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        pos = (rr + dr, cc + dc)
                        if pos in remaining:
                            remaining.remove(pos)
                            comp.add(pos)
                            stack.append(pos)
            components.append(comp)

        motif_cells = max(components, key=len)
        motif_color = color
        break

    if motif_cells is None:
        return [row[:] for row in grid]

    top = min(rr for rr, _ in motif_cells)
    left = min(cc for _, cc in motif_cells)
    bottom = max(rr for rr, _ in motif_cells)
    motif_h = bottom - top + 1
    motif = {(rr - top, cc - left) for rr, cc in motif_cells}
    color_index = palette.index(motif_color)
    first_top = top - color_index * motif_h

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        for dr, dc in motif:
            rr = first_top + i * motif_h + dr
            cc = left + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
